import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { ShieldAlert, Activity, Users, Bell, X, MapPin, TrendingUp, AlertTriangle, Info, History } from 'lucide-react';
import { getTransactions, getUserStatus } from './api';

const App = () => {
  const [transactions, setTransactions] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userHistory, setUserHistory] = useState(null);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    const fetchData = () => {
      getTransactions().then(res => setTransactions(res.data)).catch(e => console.error("API Error"));
    };
    fetchData();
    const interval = setInterval(fetchData, 3000);
    return () => clearInterval(interval);
  }, []);

  // Belirli bir kullanıcıyı detaylı inceleme ekranı (İster 4)
  const openUserDetail = (userId) => {
    getUserStatus(userId).then(res => {
      setUserHistory(res.data);
      setSelectedUser(userId);
      setShowModal(true);
    });
  };

  const chartData = transactions.slice(0, 15).reverse().map((t) => ({
    time: new Date(t.timestamp).toLocaleTimeString([], { hour12: false }),
    amount: t.amount,
  }));

  return (
    <div className="min-h-screen bg-[#020617] text-slate-400 font-mono text-[12px] overflow-x-hidden selection:bg-blue-500/30">

      {/* Üst Navigasyon */}
      <nav className="border-b border-slate-800 bg-[#0f172a] px-6 py-2 flex justify-between items-center sticky top-0 z-40">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2 border-r border-slate-800 pr-6">
            <ShieldAlert className="text-red-500" size={16} />
            <h1 className="font-black text-slate-100 tracking-tighter text-sm uppercase">Sentinel_System</h1>
          </div>
          <div className="hidden md:flex gap-6">
            <KPI simple label="ACTIVE_TX" value={transactions.length} />
            <KPI simple label="FRAUD_COUNT" value={transactions.filter(t => t.status === 'FRAUD').length} color="text-red-500" />
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500/5 border border-emerald-500/20 px-2 py-1 rounded text-emerald-500 font-bold flex items-center gap-2">
            <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div> MONITORING_LIVE
          </div>
          <Bell size={14} className="hover:text-white cursor-pointer" />
        </div>
      </nav>

      <main className="p-4 grid grid-cols-12 gap-4 max-w-[1800px] mx-auto">

        {/* SOL: Canlı Akış ve Ana Grafik */}
        <div className="col-span-12 lg:col-span-8 space-y-4">

          {/* Canlı Veri Akış Listesi (İster 1) */}
          <section className="bg-[#0f172a] border border-slate-800 rounded">
            <div className="px-4 py-2 border-b border-slate-800 bg-slate-900/30 font-bold text-slate-200 flex justify-between uppercase text-[10px] tracking-widest">
              Live_Transaction_Stream <span>{transactions.length} Records</span>
            </div>
            <div className="max-h-[400px] overflow-y-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-[#020617] text-slate-600 uppercase text-[10px] sticky top-0">
                  <tr>
                    <th className="px-4 py-2 font-medium">Timestamp</th>
                    <th className="px-4 py-2 font-medium">Entity_UID</th>
                    <th className="px-4 py-2 font-medium">Volume</th>
                    <th className="px-4 py-2 font-medium text-right">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/40">
                  {transactions.map((tx) => (
                    <tr key={tx.id} onClick={() => openUserDetail(tx.user_id)} className="hover:bg-blue-500/5 cursor-pointer transition-colors group">
                      <td className="px-4 py-2.5 font-mono text-slate-500">{new Date(tx.timestamp).toLocaleTimeString()}</td>
                      <td className="px-4 py-2.5 font-bold text-slate-300">USER_{tx.user_id}</td>
                      <td className="px-4 py-2.5 tabular-nums text-blue-400 font-bold">{tx.amount.toLocaleString()} TL</td>
                      <td className="px-4 py-2.5 text-right">
                        <span className={`px-2 py-0.5 rounded-sm font-black text-[9px] border ${
                          tx.status === 'FRAUD' ? 'bg-red-950/30 border-red-500/40 text-red-500' : 'bg-emerald-950/30 border-emerald-500/40 text-emerald-500'
                        }`}>
                          {tx.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          {/* Grafik Paneli (İster 2) */}
          <section className="bg-[#0f172a] border border-slate-800 rounded p-4 h-[250px]">
            <h3 className="font-bold text-slate-500 uppercase text-[10px] mb-4 flex items-center gap-2">
               <TrendingUp size={12}/> Fraud_Anomaly_Detection_Chart
            </h3>
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                <XAxis dataKey="time" hide />
                <YAxis hide />
                <Tooltip contentStyle={{backgroundColor: '#020617', border: '1px solid #1e293b'}} />
                <Area type="stepAfter" dataKey="amount" stroke="#3b82f6" fill="#3b82f610" strokeWidth={1.5} />
              </AreaChart>
            </ResponsiveContainer>
          </section>
        </div>

        {/* SAĞ: Uyarı Paneli ve Detay Özet */}
        <div className="col-span-12 lg:col-span-4 space-y-4">

          {/* Anlık Uyarı Paneli (İster 3) */}
          <section className="bg-red-500/5 border border-red-500/20 rounded p-4 overflow-hidden relative">
            <h3 className="text-red-500 font-black text-[10px] uppercase mb-4 flex items-center gap-2 animate-pulse">
              <AlertTriangle size={14}/> Critical_Alert_System
            </h3>
            <div className="space-y-2">
              {transactions.filter(t => t.status === 'FRAUD').slice(0, 3).map(f => (
                <div key={f.id} className="p-3 bg-[#020617] border-l-2 border-red-500 flex justify-between items-center group">
                  <div>
                    <p className="text-slate-100 font-bold">USR-{f.user_id}</p>
                    <p className="text-[10px] text-slate-500 italic">Flagged: High Volume Anomaly</p>
                  </div>
                  <button onClick={() => openUserDetail(f.user_id)} className="bg-red-500 text-white p-1 rounded hover:bg-red-400 transition-colors">
                    <Search size={12}/>
                  </button>
                </div>
              ))}
            </div>
          </section>

          {/* Quick Stats Panel */}
          <section className="bg-[#0f172a] border border-slate-800 rounded p-5">
            <h3 className="text-slate-500 font-bold text-[10px] uppercase mb-6 flex items-center gap-2">
              <Info size={12}/> Analyst_Quick_Review
            </h3>
            <div className="text-center py-10 opacity-30">
              <Users size={40} className="mx-auto mb-2" />
              <p className="italic">Click any transaction <br/> to initiate deep dive analysis.</p>
            </div>
          </section>
        </div>
      </main>

      {/* 🚩 DETAYLI ANALİZ MODALI (İster 4) */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#020617]/90 backdrop-blur-sm transition-all animate-in fade-in">
          <div className="bg-[#0f172a] border border-slate-700 rounded w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
            {/* Modal Header */}
            <div className="p-4 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-blue-600 rounded flex items-center justify-center text-white font-bold text-lg">U</div>
                <div>
                  <h2 className="text-slate-100 font-black text-sm uppercase">Entity_Deep_Dive: USR-{selectedUser}</h2>
                  <p className="text-[10px] text-blue-400 tracking-widest uppercase">Investigation_Report_0428</p>
                </div>
              </div>
              <button onClick={() => setShowModal(false)} className="text-slate-500 hover:text-white transition-colors">
                <X size={20} />
              </button>
            </div>

            {/* Modal Content */}
            <div className="p-6 overflow-y-auto grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Analiz Sol Taraf: Özet ve AI Açıklama */}
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <DetailBox label="Total_Transactions" value={userHistory?.total_transactions || 0} />
                  <DetailBox label="Anomaly_Count" value={userHistory?.fraud_count || 0} color="text-red-500" />
                </div>

                <div className="p-4 bg-[#020617] border border-blue-500/20 rounded">
                   <h4 className="text-[10px] font-black text-blue-500 uppercase mb-2 flex items-center gap-2">
                     <Activity size={12}/> AI_Logic_Explanation
                   </h4>
                   <p className="text-[11px] text-slate-400 font-mono leading-relaxed italic">
                    {userHistory?.fraud_count > 0 
                      ? "> ALERT: Account activity deviates from standard baseline. Multi-location login detected in 5min window. Transaction volume exceeds threshold."
                      : "> STATUS: Behavioral signature verified. All geolocation and volume metrics are within safe operational parameters."}
                   </p>
                </div>
              </div>

              {/* Analiz Sağ Taraf: İşlem Geçmişi (Timeline) */}
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-500 uppercase flex items-center gap-2">
                  <History size={12}/> Transaction_History_Timeline
                </h4>
                <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                   {transactions.filter(t => t.user_id === selectedUser).map((h, i) => (
                     <div key={i} className="flex items-center justify-between p-3 bg-[#020617] border border-slate-800 rounded group">
                        <div className="flex items-center gap-3">
                           <div className={`w-1.5 h-1.5 rounded-full ${h.status === 'FRAUD' ? 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]' : 'bg-emerald-500'}`}></div>
                           <span className="text-[11px] text-slate-400 font-mono">{new Date(h.timestamp).toLocaleTimeString()}</span>
                        </div>
                        <span className="text-slate-200 font-bold tabular-nums">{h.amount.toLocaleString()} TL</span>
                     </div>
                   ))}
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="p-4 border-t border-slate-700 bg-slate-900/30 text-right">
              <button className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-1.5 rounded font-bold uppercase tracking-widest text-[10px] transition-colors shadow-lg">
                Mark_For_Investigation
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Alt Komponentler
const KPI = ({ label, value, color = "text-blue-500", simple = false }) => (
  <div className="flex flex-col">
    <span className="text-[9px] font-black text-slate-600 uppercase tracking-tighter">{label}</span>
    <span className={`text-xs font-black tabular-nums ${color}`}>{value}</span>
  </div>
);

const DetailBox = ({ label, value, color = "text-slate-100" }) => (
  <div className="bg-[#020617] border border-slate-800 p-4 rounded text-center">
    <p className="text-[9px] font-bold text-slate-600 uppercase mb-1 tracking-widest">{label}</p>
    <p className={`text-xl font-black tabular-nums ${color}`}>{value}</p>
  </div>
);

export default App;
